const crypto=require('crypto');
const secret='QA_SHADOW_HMAC_ONLY_NEVER_META_CREDENTIAL';
const now=Date.now();
const m=(id,page='9900000001',opt={})=>{
 const mid=opt.mid||'QA_V171C_MID_'+id;
 const msg={sender:{id:'9900000999'},recipient:{id:opt.recipient||page},timestamp:now+(opt.age_ms||0),
   message:{mid,text:opt.text===undefined?'QA_SKU_001':opt.text,...(opt.echo?{is_echo:true}:{})}};
 const body={object:'page',entry:[{id:page,messaging:[msg]}],...(opt.storeClaim?{store_id:'QA_STORE_B'}:{}),
  ...(opt.botClaim?{bot_id:'QA_BOT_B'}:{}),...(opt.tenantClaim?{tenant_id:'QA_TENANT_2'}:{})};
 const raw=JSON.stringify(body);
 const sig='sha256='+crypto.createHmac('sha256',secret).update(raw).digest('hex');
 return {case_id:id,expected:opt.expected||'QA_ALLOW',route:opt.route||'QA_SHADOW_META_ONLY',
  raw_body:opt.empty?'':raw,header:opt.missing?'':opt.badSig?('sha256='+('f'.repeat(64))):
   opt.badFormat?('SHA256='+sig.slice(7)):sig,fixture_only:true};
};
const first=m('QA_V171C_01');
const cases=[
 first,
 m('QA_V171C_02','9900000002'),
 m('QA_V171C_03','9900000001',{badSig:true,expected:'QA_DENY'}),
 m('QA_V171C_04','9900000001',{missing:true,expected:'QA_DENY'}),
 m('QA_V171C_05','9900000001',{recipient:'9900000002',expected:'QA_DENY'}),
 m('QA_V171C_06','9900000001',{storeClaim:true,expected:'QA_DENY'}),
 m('QA_V171C_07','9900000004',{expected:'QA_DENY'}),
 m('QA_V171C_08','9900000003',{expected:'QA_DENY'}),
 m('QA_V171C_09','9900000001',{age_ms:-3600000,expected:'QA_DENY'}),
 m('QA_V171C_10','9900000001',{age_ms:3600000,expected:'QA_DENY'}),
 m('QA_V171C_11','9900000001',{echo:true,expected:'QA_DENY'}),
 {...first,case_id:'QA_V171C_12',expected:'QA_DUPLICATE'},
 m('QA_V171C_13','9900000001',{mid:'QA_V171C_MID_QA_V171C_01',text:'QA_CHANGED',expected:'QA_DENY'}),
 m('QA_V171C_14','9900000001',{botClaim:true,expected:'QA_DENY'}),
 m('QA_V171C_15','9900000001',{empty:true,expected:'QA_DENY'}),
 m('QA_V171C_16','9900000001',{route:'QA_WRONG_ROUTE',expected:'QA_DENY'}),
 m('QA_V171C_17','9900000001',{badFormat:true,expected:'QA_DENY'}),
 m('QA_V171C_18','9900000001',{tenantClaim:true,expected:'QA_DENY'}),
 m('QA_V171C_19','9900000002',{mid:'QA_V171C_MID_NEW_B',expected:'QA_ALLOW'}),
 m('QA_V171C_20','9900000001',{text:'',expected:'QA_DENY'})
];
return [{json:{contract:'V171C_SYNTHETIC_INGRESS_BATCH_ONLY',source_tag:'MANUAL_TRIGGER_NO_WEBHOOK',cases}}];

const crypto=require('crypto');
const key='QA_SHADOW_HMAC_ONLY_NEVER_META_CREDENTIAL';
const first=$input.first()?.json;
if(first?.contract!=='V171C_SYNTHETIC_INGRESS_BATCH_ONLY'||
 first.source_tag!=='MANUAL_TRIGGER_NO_WEBHOOK'||!Array.isArray(first.cases)||first.cases.length!==20)throw Error('INVALID_QA_INPUT_BATCH');
const seen=new Map(),attestations=[];
for(const caseInfo of first.cases){
 const c=caseInfo;
 let status='QA_DENY',reason='UNVERIFIED',installation_ref=null,source_class='NOT_VERIFIED';
 try{
  if(c.fixture_only!==true||!/^QA_V171C_\d\d$/.test(c.case_id))throw Error('NON_QA_ENVELOPE');
  if(c.route!=='QA_SHADOW_META_ONLY')throw Error('UNAPPROVED_SHADOW_ROUTE');
  if(typeof c.raw_body!=='string'||c.raw_body.length<5||c.raw_body.length>3500)throw Error('INVALID_BODY_LENGTH');
  if(typeof c.header!=='string'||!/^sha256=[a-f0-9]{64}$/.test(c.header))throw Error('MISSING_META_HMAC');
  const computed='sha256='+crypto.createHmac('sha256',key).update(c.raw_body).digest('hex');
  if(!crypto.timingSafeEqual(Buffer.from(computed,'utf8'),Buffer.from(c.header,'utf8')))throw Error('BAD_META_HMAC');
  const p=JSON.parse(c.raw_body);
  if(p.tenant_id!==undefined||p.store_id!==undefined||p.bot_id!==undefined||p.verification_status!==undefined)throw Error('CLIENT_SCOPE_SPOOF');
  if(p.object!=='page'||!Array.isArray(p.entry)||p.entry.length!==1)throw Error('BAD_META_ENVELOPE');
  const e=p.entry[0],item=e.messaging?.[0];
  if(!e||!/^990000000[1-9]$/.test(String(e.id||''))||!Array.isArray(e.messaging)||e.messaging.length!==1)throw Error('NOT_QA_PAGE');
  if(item?.recipient?.id!==e.id||String(item?.sender?.id)!=='9900000999')throw Error('WRONG_META_RECIPIENT');
  if(!Number.isSafeInteger(item.timestamp)||Math.abs(Date.now()-item.timestamp)>300000)throw Error('STALE_OR_FUTURE_META_EVENT');
  if(item.message?.is_echo===true||item.message?.is_deleted===true||item.message?.is_unsupported===true)throw Error('ECHO_OR_UNSUPPORTED');
  if(typeof item.message?.mid!=='string'||!/^QA_V171C_MID_[A-Z0-9_]+$/.test(item.message.mid))throw Error('UNTRUSTED_MID');
  if(typeof item.message.text!=='string'||item.message.text.length<1||item.message.text.length>300)throw Error('MESSAGE_TYPE_NOT_SUPPORTED');
  const replayKey=e.id+'|'+item.message.mid,hash=crypto.createHash('sha256').update(c.raw_body).digest('hex');
  if(seen.has(replayKey)){
   if(seen.get(replayKey)!==hash)throw Error('CONFLICTING_MID_REPLAY');
   status='QA_DUPLICATE';reason='IDENTICAL_MESSAGE_REPLAY';source_class='QA_HMAC_ONLY';
  }else{
   seen.set(replayKey,hash);status='QA_PRE_VERIFIED';reason='QA_HMAC_VALID';source_class='QA_HMAC_ONLY';
  }
  installation_ref='QA_PAGE_'+e.id;
 }catch(err){status='QA_DENY';reason=String(err?.message||'UNVERIFIED').slice(0,70);source_class='NOT_VERIFIED';}
 attestations.push({case_id:c.case_id,expected:c.expected,status,reason,installation_ref,source_class});
}
return [{json:{contract:first.contract,source_tag:first.source_tag,attestations}}];

const s=$('Verify Raw Meta QA Signature and Normalize').first()?.json;
if(s?.contract!=='V171C_SYNTHETIC_INGRESS_BATCH_ONLY'||!Array.isArray(s.attestations)||s.attestations.length!==20)
 throw Error('MISSING_VERIFIED_QA_BATCH');
const db=$input.all().map(x=>x.json||{});
if(db.length!==3)throw Error('QA_BINDING_REGISTRY_ROW_COUNT_MISMATCH');
const allowedSchema=['channel','installation_ref','tenant_ref','store_ref','bot_profile_ref','bot_version','prompt_version','knowledge_version','policy_version','approval_scope','binding_status','owner_authority_verified','read_only'];
const results=s.attestations.map(a=>{
 let status=a.status,reason=a.reason,store=null,bot=null,price=null;
 if(status==='QA_PRE_VERIFIED'){
  const matches=db.filter(row=>row.channel==='messenger'&&row.installation_ref===a.installation_ref);
  if(matches.length!==1){status='QA_DENY';reason='UNBOUND_OR_DUPLICATE_INSTALLATION';}
  else {
   const r=matches[0];
   const valid=allowedSchema.every(k=>Object.hasOwn(r,k))&&
    r.approval_scope==='SYNTHETIC_ONLY'&&r.binding_status==='QA_APPROVED'&&
    r.owner_authority_verified===false&&r.read_only===true&&
    /^QA_TENANT_[12]$/.test(r.tenant_ref)&&/^QA_STORE_[AB]$/.test(r.store_ref)&&
    /^QA_BOT_[AB]$/.test(r.bot_profile_ref)&&
    r.bot_version===r.bot_profile_ref+'_V1'&&/^QA_PROMPT_[AB]_V1$/.test(r.prompt_version)&&
    /^QA_KNOWLEDGE_[AB]_V1$/.test(r.knowledge_version)&&r.policy_version==='QA_POLICY_V1'&&
    ((r.store_ref==='QA_STORE_A'&&r.bot_profile_ref==='QA_BOT_A')||(r.store_ref==='QA_STORE_B'&&r.bot_profile_ref==='QA_BOT_B'));
   if(!valid){status='QA_DENY';reason='INSTALLATION_POLICY_OR_STORE_BINDING_DENIED';}
   else{
    store=r.store_ref;bot=r.bot_profile_ref;price=store==='QA_STORE_A'?159000:259000;
    status='QA_ALLOW';reason='PERSISTED_QA_INSTALLATION_BINDS_BOT';
   }
  }
 }
 return {case_id:a.case_id,expected:a.expected,status,reason,
  trusted_store:store,trusted_bot:bot,price_vnd:price,
  source_attestation:a.source_class,raw_provider_event_replayed:false,
  real_page_owner_verified:false,hosted_store_rls_verified:false,model_calls:0,provider_sends:0,orders_written:0};
});
if(results.length!==20||results.some(x=>x.status!==x.expected))throw Error('P0_SHADOW_BINDING_QA_EXPECTATION_FAILED');
for(const r of results){
 if(r.model_calls!==0||r.provider_sends!==0||r.orders_written!==0)throw Error('REAL_ACTION_GATE_FAILED');
 if(r.status==='QA_ALLOW'&&(!r.trusted_store||!r.trusted_bot||!r.price_vnd))throw Error('AUTHORIZED_QA_BINDING_EMPTY');
 if(r.status==='QA_DENY'&&(r.trusted_store||r.trusted_bot))throw Error('BLOCKED_SCOPE_LEAK');
}
return [{json:{status:'V171C_SHADOW_PERSISTED_REGISTRY_QA_PASS',suite:'MANUAL_SYNTHETIC_ONLY_NO_WEBHOOK',total:results.length,
 passed:results.length,allowed:results.filter(x=>x.status==='QA_ALLOW').length,
 denied:results.filter(x=>x.status==='QA_DENY').length,
 duplicate:results.filter(x=>x.status==='QA_DUPLICATE').length,
 registry_records:db.length,registry_type:'N8N_PERSISTENT_QA_ONLY',
 page_owner_verified:false,hosted_store_rls_verified:false,
 real_meta_webhook_received:false,send:'MOCK_ONLY_NOT_SENT',
 provider_sends:0,orders_written:0,model_calls:0,
 cases:results.map(x=>({case_id:x.case_id,status:x.status,reason:x.reason,store:x.trusted_store,bot:x.trusted_bot,price_vnd:x.price_vnd}))}}];
